// Helper function to calculate the sum of odd elements in even positions
function SumOddEvenPosition(lst: seq<int>): int
    requires |lst| > 0
{
    var sum := 0;
    var i := 0;
    while i < |lst|
        invariant 0 <= i <= |lst|
        invariant sum == SumOddEvenPositionHelper(lst, i)
    {
        if i % 2 == 0 && lst[i] % 2 != 0 {
            sum := sum + lst[i];
        }
        i := i + 1;
    }
    return sum;
}

function SumOddEvenPositionHelper(lst: seq<int>, i: int): int
    requires |lst| > 0
    requires 0 <= i <= |lst|
{
    var sum := 0;
    var j := 0;
    while j < i
        invariant 0 <= j <= i
        invariant sum == SumOddEvenPositionAccum(lst, j)
    {
        if j % 2 == 0 && lst[j] % 2 != 0 {
            sum := sum + lst[j];
        }
        j := j + 1;
    }
    return sum;
}

function SumOddEvenPositionAccum(lst: seq<int>, j: int): int
    requires |lst| > 0
    requires 0 <= j <= |lst|
{
    var total := 0;
    var k := 0;
    while k < j
        invariant 0 <= k <= j
    {
        if k % 2 == 0 && lst[k] % 2 != 0 {
            total := total + lst[k];
        }
        k := k + 1;
    }
    return total;
}

